input.content:
locals {
  common_tags = {
    Project   = var.project
    ManagedBy = "terraform"
  }

  account_root  = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
  fallback_admin = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/${var.fallback_admin_role_name}"

  # Empty in accounts where the baseline has yet to land. That is a legitimate
  # state, so the config folds in whatever it finds and the checks report the gap.
  platform_admin_arns = tolist(data.aws_iam_roles.platform_admin.arns)
  break_glass_arns    = tolist(data.aws_iam_roles.break_glass.arns)

  key_admin_principals = concat(
    [local.fallback_admin],
    local.platform_admin_arns,
    local.break_glass_arns,
  )

  # The administration surface, spelled out. `kms:*` would also hand out Decrypt
  # and GenerateDataKey, which administrators have no business holding.
  key_admin_actions = [
    "kms:CancelKeyDeletion",
    "kms:Create*",
    "kms:Delete*",
    "kms:Describe*",
    "kms:Disable*",
    "kms:Enable*",
    "kms:Get*",
    "kms:List*",
    "kms:Put*",
    "kms:Revoke*",
    "kms:RotateKeyOnDemand",
    "kms:ScheduleKeyDeletion",
    "kms:TagResource",
    "kms:UntagResource",
    "kms:Update*",
  ]

  key_usage_actions = [
    "kms:Decrypt",
    "kms:DescribeKey",
    "kms:Encrypt",
    "kms:GenerateDataKey*",
    "kms:ReEncrypt*",
  ]
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_organizations_organization" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

# ---------------------------------------------------------------------------
# Top-level lookups: these FEED the policy, so they have to live out here. The
# plural data source returns an empty set when nothing matches, where the
# singular `aws_iam_role` raises an error and fails the plan - that difference
# is what lets one module deploy across accounts at different baseline stages.
#
# The check blocks at the bottom re-read the same roles through their own scoped
# data sources. That is deliberate: a check observes reality rather than trusting
# what the configuration computed, and a scoped data source is invisible to
# everything outside its own check.
# ---------------------------------------------------------------------------
data "aws_iam_roles" "platform_admin" {
  name_regex = "^${var.platform_admin_role_name}$"
}

data "aws_iam_roles" "break_glass" {
  name_regex = "^${var.break_glass_role_name}$"
}

# ---------------------------------------------------------------------------
# Key policy. Five statements, following the AWS key-policy baseline.
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "key" {
  # 1. The delegation AWS documents: it lets IAM policies in this account govern
  #    the key, and it is the safety net that keeps the key administrable.
  statement {
    sid       = "EnableIAMUserPermissions"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root]
    }
  }

  # 2. Administration, restricted to named principals. The fallback admin is
  #    unconditional; the baseline roles join only where they exist.
  statement {
    sid       = "KeyAdministration"
    actions   = local.key_admin_actions
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = local.key_admin_principals
    }
  }

  # 3. Usage, and only through S3. A leaked credential cannot call Decrypt
  #    directly - the request has to arrive via the service.
  statement {
    sid       = "KeyUsageByApplicationViaS3"
    actions   = local.key_usage_actions
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.app.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.region}.amazonaws.com"]
    }
  }

  # 4. Grants, restricted to those an AWS service creates on the caller's behalf
  #    (S3 needs one to encrypt objects with this key).
  statement {
    sid       = "AllowGrantsForAWSServices"
    actions   = ["kms:CreateGrant", "kms:ListGrants", "kms:RevokeGrant"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.app.arn]
    }

    condition {
      test     = "Bool"
      variable = "kms:GrantIsForAWSResource"
      values   = ["true"]
    }
  }

  # 5. The perimeter: nothing outside the organization touches this key. The
  #    second condition spares AWS service principals, which carry no
  #    aws:PrincipalOrgID and would otherwise be denied along with everyone else.
  dynamic "statement" {
    for_each = var.enable_org_deny ? [1] : []

    content {
      sid       = "DenyOutsideOrganization"
      effect    = "Deny"
      actions   = ["kms:*"]
      resources = ["*"]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "StringNotEquals"
        variable = "aws:PrincipalOrgID"
        values   = [data.aws_organizations_organization.current.id]
      }

      condition {
        test     = "BoolIfExists"
        variable = "aws:PrincipalIsAWSService"
        values   = ["false"]
      }
    }
  }
}

resource "aws_kms_key" "app" {
  description             = "Demo key whose administrators depend on what exists in this account"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.key.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "app" {
  name          = "alias/${var.project}"
  target_key_id = aws_kms_key.app.key_id
}

# ---------------------------------------------------------------------------
# Something that actually uses the key, so the policy above governs real traffic
# rather than staying theoretical.
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "app_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "app" {
  name               = "${var.project}-app"
  description        = "Application role granted encrypted access to the demo bucket"
  assume_role_policy = data.aws_iam_policy_document.app_assume.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "app_bucket_access" {
  statement {
    actions   = ["s3:GetObject", "s3:PutObject"]
    resources = ["${aws_s3_bucket.data.arn}/*"]
  }
}

resource "aws_iam_role_policy" "app_bucket_access" {
  name   = "bucket-access"
  role   = aws_iam_role.app.id
  policy = data.aws_iam_policy_document.app_bucket_access.json
}

resource "aws_s3_bucket" "data" {
  bucket = "${var.project}-${random_id.suffix.hex}"
  tags   = local.common_tags
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket                  = aws_s3_bucket.data.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "data" {
  bucket = aws_s3_bucket.data.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data" {
  bucket = aws_s3_bucket.data.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.app.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# The checks. Each carries its own scoped data source, re-read on every plan and
# apply, and reachable from nowhere else in the configuration.
#
# Both report as WARNINGS. An account still waiting on the baseline, or a key an
# operator disabled by hand, are things to know about - blocking every deployment
# over them would be the wrong trade.
# ---------------------------------------------------------------------------
check "break_glass_role_present" {
  data "aws_iam_roles" "break_glass_observed" {
    name_regex = "^${var.break_glass_role_name}$"
  }

  assert {
    condition     = length(data.aws_iam_roles.break_glass_observed.arns) > 0
    error_message = "Emergency access role '${var.break_glass_role_name}' is absent from this account, so the key policy grants administration without it. Expected once the platform baseline reaches this account."
  }
}

check "platform_admin_role_present" {
  data "aws_iam_roles" "platform_admin_observed" {
    name_regex = "^${var.platform_admin_role_name}$"
  }

  assert {
    condition     = length(data.aws_iam_roles.platform_admin_observed.arns) > 0
    error_message = "Platform administration role '${var.platform_admin_role_name}' is absent from this account, so the key policy grants administration without it. Expected once the platform baseline reaches this account."
  }
}

check "key_operational" {
  data "aws_kms_key" "deployed" {
    key_id = aws_kms_key.app.key_id
  }

  assert {
    condition     = data.aws_kms_key.deployed.key_state == "Enabled"
    error_message = "Key ${aws_kms_key.app.key_id} reports state '${data.aws_kms_key.deployed.key_state}': anything other than Enabled means the bucket can no longer encrypt or read its objects."
  }
}

